const cases=['cancel-before-mutation','cancel-after-mutation','logout-held'],rows=[],raw=[];const assert=(value,label)=>{if(!value)throw Error(label)};
for(const name of cases){const events=[],controller=new AbortController(),signal=controller.signal,reason={fixture:'cancel-'+name},credential={type:'api_key',key:'fixture-owned'},gate=()=>{let resolve;const promise=new Promise(r=>resolve=r);return{promise,resolve}},entered=gate(),started=gate(),begin=gate(),commit=gate(),finished=gate();let stored=name==='logout-held'?credential:undefined,callbackCalls=0;
const credentials={async read(){return stored},async list(){return[]},async modify(id,fn,options){events.push('modify-enter');entered.resolve();try{await begin.promise;options.signal.throwIfAborted();callbackCalls++;events.push('mutation-start');const next=await fn(stored);started.resolve();await commit.promise;if(next!==undefined)stored=next;events.push('mutation-commit');return stored}finally{finished.resolve()}},async delete(id,options){options.signal.throwIfAborted();events.push('delete-enter');entered.resolve();await commit.promise;stored=undefined;events.push('delete-commit');finished.resolve()}};
const models=A.createModels({credentials});models.setProvider(A.createProvider({id:'fixture',models:[],auth:{apiKey:{name:'Fixture',resolve:async()=>undefined,login:async()=>{events.push('login');return credential}}},api:{stream(){throw Error('unused')},streamSimple(){throw Error('unused')}}}));let settled=false;const pending=name==='logout-held'?models.logout('fixture',{signal}):models.login('fixture','api_key',{signal});void pending.then(()=>{settled=true},()=>{settled=true});await entered.promise;
if(name==='cancel-after-mutation'){begin.resolve();await started.promise}controller.abort(reason);events.push('abort');for(let i=0;i<5;i++)await Promise.resolve();const settledBeforeRelease=settled;let value,rejectedSame=false;if(name==='cancel-before-mutation'){try{await pending;throw Error('missing cancel')}catch(error){rejectedSame=error===reason;if(!rejectedSame)throw error}begin.resolve();commit.resolve();await finished.promise}else{assert(!settledBeforeRelease,'eager termination after mutation');commit.resolve();value=await pending;await finished.promise}
if(name==='cancel-before-mutation')assert(rejectedSame&&callbackCalls===0&&stored===undefined,'queued cancellation');else if(name==='cancel-after-mutation')assert(value===credential&&stored===credential&&callbackCalls===1,'committed mutation lost');else assert(value===undefined&&stored===undefined,'logout not committed');rows.push({name,events,settledBeforeRelease,rejectedSame,callbackCalls,valueType:typeof value,returnedIdentity:value===credential,storedType:typeof stored,storedIdentity:stored===credential});raw.push({...rows.at(-1),value,stored})}
